<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {copyText} from '../state'
import Brand from './Brand.vue'
import Icon from './Icon.vue'
const props=defineProps({order:Object,qrSource:String,busy:Boolean,error:String,embedded:Boolean,cardClass:String,zh:{type:Boolean,default:true}}),emit=defineEmits(['refresh'])
const t=(cn,en)=>props.zh?cn:en,now=ref(Date.now()),offset=ref(0),copied=ref('')
watch(()=>props.order?.server_now,value=>{if(value)offset.value=value*1000-Date.now()},{immediate:true})
const serverNow=computed(()=>now.value+offset.value)
const crypto=computed(()=>props.order?.crypto||props.order?.payment_payload||{})
const phase=computed(()=>{const o=props.order;if(!o)return 'loading';if(o.status==='REFUNDED')return 'refunded';if(o.status==='REFUNDING')return 'refunding';if(o.paid||o.paid_at)return 'paid';if(o.risk_hold)return 'risk';if(o.status==='CONFIRMING')return 'confirming';if(o.status==='EXPIRED'||(o.status==='CREATED'&&o.expires_at*1000<=serverNow.value))return 'expired';if(o.status==='CLOSED')return 'closed';return 'waiting'})
const amount=computed(()=>props.order?.payment_amount||(props.order?.channel==='crypto'?crypto.value.crypto_amount:props.order?.amount)||'0.00')
const currency=computed(()=>props.order?.payment_currency||(props.order?.channel==='crypto'?crypto.value.asset:'CNY'))
const network=computed(()=>props.order?.crypto_network||crypto.value.network||'')
const address=computed(()=>props.order?.crypto_address||crypto.value.address||'')
const remaining=computed(()=>Math.max(0,Math.ceil((props.order?.expires_at||0)-serverNow.value/1000)))
const countdown=computed(()=>t(`${Math.floor(remaining.value/60)} 分 ${String(remaining.value%60).padStart(2,'0')} 秒`,`${Math.floor(remaining.value/60)}m ${String(remaining.value%60).padStart(2,'0')}s`))
const style=computed(()=>{const o=props.order;return {'--cashier-color':o?.channel==='alipay'?'#1677ee':o?.channel==='wechat'?'#13965b':currency.value==='USDC'?'#2775ca':'#168b73','--cashier-w':`${Math.min(740,Math.max(Number(o?.layout?.cashier_width)||440,(o?.subject?.length||0)*7+(o?.out_trade_no?.length||0)*6+70))}px`}})
const progress=computed(()=>{const o=props.order;if(!o)return 0;const at=o.progress_frozen_at||o.paid_at||serverNow.value/1000;return Math.min(100,Math.max(0,(at-o.created_at)/Math.max(1,o.expires_at-o.created_at)*100))})
const created=computed(()=>{if(!props.order?.created_at)return '−';const d=new Date(props.order.created_at*1000),pad=value=>String(value).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`})
const zone=Intl.DateTimeFormat(undefined,{timeZoneName:'shortOffset'}).formatToParts(new Date()).find(part=>part.type==='timeZoneName')?.value||''
async function copy(value,key){try{await copyText(String(value));copied.value=key;setTimeout(()=>copied.value='',1600)}catch{copied.value=''}}
let timer
onMounted(()=>timer=setInterval(()=>now.value=Date.now(),1000));onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="cashier-page" :class="{embedded}" :style="style"><section class="cashier-card" :class="[cardClass,`is-${phase}`]" :aria-busy="busy">
<svg class="cashier-border" viewBox="0 0 1000 1500" preserveAspectRatio="none" aria-hidden="true"><path pathLength="100" :stroke-dashoffset="-progress" d="M 960 0 A 40 40 0 0 1 1000 40 V 1460 A 40 40 0 0 1 960 1500 H 40 A 40 40 0 0 1 0 1460 V 40 A 40 40 0 0 1 40 0 H 960"/></svg>
<header class="cashier-head"><div class="cashier-brand"><Brand name="bingyun"/><span>{{t('冰云支付','BingYun Pay')}}</span></div><a v-if="phase==='paid'&&order?.return_available" class="cashier-return" :href="order.return_href" target="_top">{{t('返回站点','Back to site')}}<Icon name="arrow" :size="16"/></a><span v-else class="cashier-secure"><Icon name="shield" :size="17"/>{{t('安全支付','Secure checkout')}}</span></header>
<template v-if="phase==='waiting'"><div class="cashier-amount-label">{{t('支付金额','Payment amount')}}</div><div class="cashier-amount"><strong>{{amount}}</strong><span class="currency-tag">{{currency}}</span></div></template>
<div v-if="order" class="cashier-order-line"><button type="button" class="cashier-subject" :title="order.subject" @click="copy(order.subject,'subject')">{{order.subject}}</button><button type="button" class="cashier-order-number" :title="order.out_trade_no" @click="copy(order.out_trade_no,'number')">{{order.out_trade_no}}</button></div>
<template v-if="phase==='waiting'"><div class="qr-frame"><span v-for="corner in ['tl','tr','bl','br']" :key="corner" class="qr-corner" :class="corner"></span><span v-for="rail in ['left','right']" :key="rail" class="scan-rail" :class="rail" aria-hidden="true"></span><img v-if="order.qr_ready&&!busy" :src="qrSource" :alt="t('付款二维码','Payment QR code')" width="240" height="240"/><div v-else class="qr-placeholder"><Icon name="loader" class="spin" :size="28"/><span>{{t('正在准备二维码','Preparing QR code')}}</span></div></div>
<p class="cashier-expiry" role="timer"><Icon name="timer" :size="18"/>{{t('订单有效期','Time remaining')}} <strong>{{countdown}}</strong></p>
<p class="cashier-instruction">{{t(`请使用 ${order.payment_method||network} 进行支付`,`Please pay using ${order.payment_method||network}`)}}</p>
<template v-if="order.channel==='crypto'"><p class="crypto-notice">{{t('请确保收款地址足额收到上方支付金额，网络手续费由您承担','Send the exact displayed amount. Network fees are paid separately.')}}</p><div class="crypto-address"><code>{{address}}</code><button class="icon-button" type="button" :aria-label="t('复制收款地址','Copy receiving address')" @click="copy(address,'address')"><Icon :name="copied==='address'?'check':'copy'" :size="16"/></button></div><button type="button" class="text-link copy-payment" @click="copy(amount,'amount')">{{copied==='amount'?t('已复制金额','Amount copied'):t('复制支付金额','Copy payment amount')}}</button></template>
<p class="cashier-created">{{t('创建时间','Created')}} {{created}} <small>{{zone}}</small></p>
<button v-if="!order.qr_ready&&!busy" class="text-link" type="button" @click="emit('refresh')">{{t('重试获取二维码','Retry QR code')}}</button>
</template>
<div v-else-if="order" class="cashier-state" :class="phase" role="status"><span class="state-symbol"><Icon :name="phase==='paid'?'success':phase==='confirming'?'loader':phase==='risk'?'shield':phase==='expired'?'timer':'alert'" :class="{spin:phase==='confirming'}" :size="48"/></span><h1>{{({paid:t('支付成功','Payment successful'),confirming:t('正在确认','Confirming payment'),expired:t('订单已过期','Order expired'),closed:t('订单已关闭','Order closed'),risk:t('订单待核对','Order requires review'),refunding:t('退款处理中','Refund in progress'),refunded:t('订单已退款','Payment refunded')})[phase]}}</h1><p v-if="phase==='paid'">{{order.risk_hold?t('款项已确认，订单正在核对','Payment confirmed; order under review'):t('感谢您对本站的支持','Thank you for your support')}}</p><p v-else-if="phase==='confirming'">{{t(`链上确认 ${crypto.confirmations||0} / ${crypto.required_confirmations||1}`,`Confirmations ${crypto.confirmations||0} / ${crypto.required_confirmations||1}`)}}</p><p v-else>{{phase==='expired'||phase==='closed'?t('请返回商户重新下单','Return to the merchant to order again'):t('请联系网站客服核对订单','Contact the website support team')}}</p></div>
<div v-else class="cashier-state"><Icon name="loader" class="spin" :size="28"/><p>{{t('正在读取订单','Loading checkout')}}</p></div>
<p class="cashier-support">{{t('如支付遇到问题，请联系网站客服','For payment assistance, contact the website support team')}}</p>
<p v-if="error" class="cashier-error" role="alert">{{t('订单状态暂未同步','Order status could not be refreshed')}} · {{error}}</p>
</section></div></template>
<style scoped>
.cashier-page{min-height:100svh;box-sizing:border-box;display:grid;justify-items:center;align-content:start;padding:clamp(16px,4vw,44px) 14px;background:radial-gradient(ellipse at 50% 0%,color-mix(in srgb,var(--cashier-color) 7%,var(--bg)),var(--bg) 60%);color:var(--text);font-family:var(--font,inherit)}.cashier-card{position:relative;isolation:isolate;box-sizing:border-box;width:min(100%,var(--cashier-w));max-width:calc(100vw - 28px);padding:26px 28px 22px;border-radius:24px;background:var(--card);box-shadow:0 16px 54px #3e2e2010,0 2px 8px #3e2e2008;overflow:hidden}.cashier-border{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0}.cashier-border path{fill:none;stroke:var(--cashier-color);stroke-width:2.5;vector-effect:non-scaling-stroke;stroke-linecap:round;stroke-dasharray:100 100;transition:stroke-dashoffset .5s linear}.cashier-head{display:flex;align-items:center;justify-content:space-between;gap:16px;position:relative;z-index:1}.cashier-brand,.cashier-secure,.cashier-return{display:inline-flex;align-items:center;gap:7px;white-space:nowrap}.cashier-brand{font-size:15px;font-weight:600}.cashier-brand :deep(img){width:26px;height:26px}.cashier-secure{font-size:12px;color:var(--muted)}.cashier-secure .bypay-icon{color:var(--cashier-color)}.cashier-return{font-size:12px;color:var(--cashier-color);text-decoration:none;min-height:32px}.cashier-amount-label{text-align:center;font-size:12px;color:var(--muted);margin-top:30px}.cashier-amount{display:flex;justify-content:center;align-items:center;gap:9px;margin:8px 0 20px;line-height:1.2}.cashier-amount strong{font-size:clamp(32px,7vw,44px);font-weight:650;letter-spacing:-.045em;font-variant-numeric:tabular-nums}.currency-tag{padding:5px 7px;border-radius:7px;background:color-mix(in srgb,var(--cashier-color) 9%,var(--card));color:var(--cashier-color);font-size:12px;font-weight:650}.cashier-order-line{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:18px;margin:18px 0;color:var(--muted)}.cashier-order-line button{border:0;background:none;padding:3px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;color:inherit;cursor:copy}.cashier-subject{text-align:left}.cashier-order-number{text-align:right;font-family:ui-monospace,monospace}.qr-frame{position:relative;width:280px;height:280px;max-width:100%;box-sizing:border-box;margin:22px auto 18px;padding:20px;background:white;overflow:hidden}.qr-frame img{display:block;width:100%;height:100%;object-fit:contain;background:white}.qr-placeholder{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#62666b;font-size:12px}.qr-corner{position:absolute;width:25px;height:25px;border-color:var(--cashier-color);border-style:solid;border-width:0;pointer-events:none}.tl{top:1px;left:1px;border-top-width:3px;border-left-width:3px;border-top-left-radius:12px}.tr{top:1px;right:1px;border-top-width:3px;border-right-width:3px;border-top-right-radius:12px}.bl{bottom:1px;left:1px;border-bottom-width:3px;border-left-width:3px;border-bottom-left-radius:12px}.br{bottom:1px;right:1px;border-bottom-width:3px;border-right-width:3px;border-bottom-right-radius:12px}.scan-rail{position:absolute;top:0;width:4px;height:64px;border-radius:8px;background:linear-gradient(transparent,color-mix(in srgb,var(--cashier-color) 60%,white),transparent);animation:scan 3.4s linear infinite;pointer-events:none}.scan-rail.left{left:8px}.scan-rail.right{right:8px;animation-delay:-1.7s}@keyframes scan{from{transform:translateY(-70px)}to{transform:translateY(290px)}}.cashier-expiry{display:flex;align-items:center;justify-content:center;gap:7px;font-size:14px;color:var(--cashier-color);margin:16px 0 9px}.cashier-expiry strong{font-variant-numeric:tabular-nums;font-weight:650}.cashier-instruction{text-align:center;font-size:13px;margin:8px 0 14px}.crypto-notice{font-size:11px;line-height:1.65;text-align:center;color:var(--muted);max-width:330px;margin:12px auto}.crypto-address{display:flex;align-items:center;gap:5px;max-width:340px;padding:6px 8px;margin:8px auto;border-radius:9px;background:var(--soft)}.crypto-address code{min-width:0;overflow-wrap:anywhere;flex:1;font-size:10px;line-height:1.6;color:var(--muted)}.crypto-address .icon-button{flex:none;width:30px;height:30px}.copy-payment{display:block;margin:5px auto;font-size:11px}.cashier-created{text-align:center;font-size:11px;color:var(--muted);margin:18px 0}.cashier-created small{font-size:10px}.cashier-support{text-align:center;font-size:11px;color:var(--muted);line-height:1.6;margin:22px 0 0}.cashier-state{min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:16px}.cashier-state h1{font-size:25px;margin:0}.cashier-state p{font-size:13px;color:var(--muted);margin:0;line-height:1.7}.state-symbol{display:flex;align-items:center;justify-content:center;width:86px;height:86px;border-radius:50%;background:var(--soft);color:var(--cashier-color)}.paid .state-symbol{color:#168052;background:#16805210}.risk .state-symbol,.expired .state-symbol{color:#b27820}.cashier-error{font-size:12px;color:#bb3434;text-align:center;line-height:1.6}.embedded{min-height:0;background:transparent;padding:12px}.embedded .cashier-card{box-shadow:none}@media(max-width:420px){.cashier-card{padding:22px 18px}.cashier-brand{font-size:14px}.cashier-secure{font-size:11px}.qr-frame{width:260px;height:260px}.cashier-order-line{gap:12px}}@media(prefers-reduced-motion:reduce){.scan-rail{animation:none;display:none}.cashier-border path{transition:none}.spin{animation:none!important}}
</style>
